-int AudioShortcutsService::changeVolumePercent(PulseAudioQt::Device *device, int deltaPercent)
+int AudioShortcutsService::changeVolumePercent(PulseAudioQt::VolumeObject *object, int deltaPercent)
 {
-    const qint64 oldVolume = device->volume();
+    const qint64 oldVolume = object->volume();
     const int oldPercent = volumePercent(oldVolume);
     const int targetPercent = oldPercent + deltaPercent;
     const int maxVolume = PulseAudioQt::normalVolume() * (m_globalConfig->raiseMaximumVolume() ? 150 : 100) / 100.0;
     const qint64 newVolume = boundVolume(std::round(PulseAudioQt::normalVolume() * (targetPercent / 100.f)), maxVolume);
     const int newPercent = volumePercent(newVolume);
-    device->setMuted(newPercent == 0);
-    device->setVolume(newVolume);
+    object->setMuted(newPercent == 0);
+    object->setVolume(newVolume);
     return newPercent;
 }

+QString AudioShortcutsService::applicationName(const PulseAudioQt::SinkInput *sinkInput)
+{
+    if (sinkInput->isVirtualStream() || !sinkInput->hasVolume() || !sinkInput->client()) {
+        return QString();
+    }
+    const QString name = sinkInput->client()->name();
+    if (name == "libcanberra"_L1 || name == "pipewire-media-session"_L1) {
+        return QString();
+    }
+    return name;
+}
+
+QList<PulseAudioQt::SinkInput *> AudioShortcutsService::applicationStreams(const QString &application) const
+{
+    QList<PulseAudioQt::SinkInput *> streams;
+    const auto sinkInputs = PulseAudioQt::Context::instance()->sinkInputs();
+    for (auto sinkInput : sinkInputs) {
+        if (applicationName(sinkInput) == application) {
+            streams.append(sinkInput);
+        }
+    }
+    return streams;
+}
+
+void AudioShortcutsService::addApplicationActions(const QString &application)
+{
+    QAction *volumeUpAction = new QAction(this);
+    volumeUpAction->setObjectName(APPLICATION_VOLUME_UP + application);
+    volumeUpAction->setText(i18nc("@action %1 is an application name", "Increase Volume of %1", application));
+    connect(volumeUpAction, &QAction::triggered, this, [this, application]() {
+        changeApplicationVolume(application, m_globalConfig->volumeStep());
+    });
+
+    QAction *volumeDownAction = new QAction(this);
+    volumeDownAction->setObjectName(APPLICATION_VOLUME_DOWN + application);
+    volumeDownAction->setText(i18nc("@action %1 is an application name", "Decrease Volume of %1", application));
+    connect(volumeDownAction, &QAction::triggered, this, [this, application]() {
+        changeApplicationVolume(application, -m_globalConfig->volumeStep());
+    });
+
+    QAction *muteAction = new QAction(this);
+    muteAction->setObjectName(APPLICATION_MUTE + application);
+    muteAction->setText(i18nc("@action %1 is an application name", "Mute %1", application));
+    connect(muteAction, &QAction::triggered, this, [this, application]() {
+        toggleApplicationMute(application);
+    });
+
+    const QList<QAction *> actions = {volumeUpAction, volumeDownAction, muteAction};
+    for (const auto action : actions) {
+        action->setProperty("componentName", u"kmix"_s);
+        action->setProperty("componentDisplayName", i18n("Audio Volume"));
+        KGlobalAccel::setGlobalShortcut(action, QList<QKeySequence>());
+    }
+    m_applicationActions.insert(application, actions);
+}
+
+void AudioShortcutsService::restoreApplicationActions()
+{
+    // Applications that were given a shortcut keep it even while they are not playing
+    QDBusMessage message =
+        QDBusMessage::createMethodCall(u"org.kde.kglobalaccel"_s, u"/component/kmix"_s, u"org.kde.kglobalaccel.Component"_s, u"shortcutNames"_s);
+    auto *watcher = new QDBusPendingCallWatcher(QDBusConnection::sessionBus().asyncCall(message), this);
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this, watcher] {
+        watcher->deleteLater();
+        QDBusPendingReply<QStringList> reply = *watcher;
+        if (reply.isError()) {
+            return;
+        }
+        const QStringList names = reply.value();
+        for (const QString &name : names) {
+            if (!name.startsWith(APPLICATION_MUTE)) {
+                continue;
+            }
+            const QString application = name.mid(APPLICATION_MUTE.size());
+            if (!application.isEmpty() && !m_applicationActions.contains(application)) {
+                addApplicationActions(application);
+            }
+        }
+        updateApplicationActions();
+    });
+}
+
+void AudioShortcutsService::updateApplicationActions()
+{
+    QSet<QString> playing;
+    const auto sinkInputs = PulseAudioQt::Context::instance()->sinkInputs();
+    for (auto sinkInput : sinkInputs) {
+        const QString application = applicationName(sinkInput);
+        if (!application.isEmpty()) {
+            playing.insert(application);
+        }
+    }
+
+    for (const QString &application : std::as_const(playing)) {
+        if (!m_applicationActions.contains(application)) {
+            addApplicationActions(application);
+        }
+    }
+
+    for (auto it = m_applicationActions.begin(); it != m_applicationActions.end();) {
+        const bool hasShortcut = std::any_of(it->cbegin(), it->cend(), [](QAction *action) {
+            return !KGlobalAccel::self()->shortcut(action).isEmpty();
+        });
+        if (playing.contains(it.key()) || hasShortcut) {
+            ++it;
+            continue;
+        }
+        for (const auto action : std::as_const(*it)) {
+            KGlobalAccel::self()->removeAllShortcuts(action);
+            delete action;
+        }
+        it = m_applicationActions.erase(it);
+    }
+}
+
+void AudioShortcutsService::changeApplicationVolume(const QString &application, int deltaPercent)
+{
+    const auto streams = applicationStreams(application);
+    if (streams.isEmpty()) {
+        return;
+    }
+    int percent = 0;
+    for (auto stream : streams) {
+        percent = changeVolumePercent(stream, deltaPercent);
+    }
+    if (m_globalConfig->volumeOsd()) {
+        showApplicationVolume(application, streams.first()->iconName(), percent);
+    }
+}
+
+void AudioShortcutsService::toggleApplicationMute(const QString &application)
+{
+    const auto streams = applicationStreams(application);
+    if (streams.isEmpty()) {
+        return;
+    }
+    const bool mute = std::any_of(streams.cbegin(), streams.cend(), [](PulseAudioQt::SinkInput *stream) {
+        return !stream->isMuted();
+    });
+    for (auto stream : streams) {
+        stream->setMuted(mute);
+    }
+    if (m_globalConfig->muteOsd()) {
+        showApplicationVolume(application, streams.first()->iconName(), mute ? 0 : volumePercent(streams.first()->volume()));
+    }
+}
+
+void AudioShortcutsService::showApplicationVolume(const QString &application, const QString &icon, int percent)
+{
+    m_osdDBusInterface->mediaPlayerVolumeChanged(percent, application, icon.isEmpty() ? u"audio-volume-high"_s : icon);
+}
